// și Unitatea 2, Punți între lumi, până la conjunctiv și
// condițional-optativ. Infinitivul, participiul, gerunziul,
// supinul, mitologia și restul unității 2 nu sunt încă aici.
// Nu copiem fragmente, poezii, citate sau anunțuri cuvânt cu cuvânt.
// Scena de care are nevoie copilul este scrisă în lecție.
// Grilele de punctaj și fișa de observare nu sunt lecții.

function lesson(id, title, block) {
  const example = String(block.example || '').replace(/^Exemplu lucrat:\s*/i, '');
  const platter = [block.theory, `Exemplu lucrat: ${example}`, block.tryThis, block.recap].join('\n\n');
  return {
    id,
    title,
    platter,
    theory: block.theory,
    example,
    tryThis: block.tryThis,
    recap: block.recap
  };
}

